INSERT INTO capabilities(code,description) VALUES ('impar.knowledge.manage','Registrar fontes e candidatos de conhecimento'),('impar.knowledge.review','Revisar candidatos de conhecimento'),('impar.knowledge.publish','Publicar conhecimento autorizado') ON CONFLICT DO NOTHING;
CREATE TABLE knowledge_sources(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),knowledge_scope TEXT NOT NULL CHECK(knowledge_scope='IMPAR'),source_type TEXT NOT NULL CHECK(source_type IN ('DOCUMENT','EXPERT_INPUT','CURATED_DATASET','OTHER')),label TEXT NOT NULL,private_content_ref TEXT NOT NULL,content_hash TEXT CHECK(content_hash IS NULL OR content_hash ~ '^[0-9a-f]{64}$'),status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','RETIRED')),created_by_principal_id UUID NOT NULL REFERENCES principals(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE knowledge_candidates(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),source_id UUID NOT NULL REFERENCES knowledge_sources(id),knowledge_scope TEXT NOT NULL CHECK(knowledge_scope='IMPAR'),candidate_version INT NOT NULL CHECK(candidate_version>0),private_content_ref TEXT NOT NULL,content_hash TEXT CHECK(content_hash IS NULL OR content_hash ~ '^[0-9a-f]{64}$'),status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','IN_REVIEW','APPROVED','PUBLISHED','REJECTED')),created_by_principal_id UUID NOT NULL REFERENCES principals(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source_id,candidate_version));
CREATE TABLE knowledge_reviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),candidate_id UUID NOT NULL REFERENCES knowledge_candidates(id),decision TEXT NOT NULL CHECK(decision IN ('APPROVE','REJECT')),reviewed_by_principal_id UUID NOT NULL REFERENCES principals(id),reviewed_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(candidate_id));
CREATE TABLE authorized_knowledge_versions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),candidate_id UUID NOT NULL UNIQUE REFERENCES knowledge_candidates(id),knowledge_scope TEXT NOT NULL CHECK(knowledge_scope='IMPAR'),version INT NOT NULL CHECK(version>0),status TEXT NOT NULL DEFAULT 'PUBLISHED' CHECK(status IN ('PUBLISHED','RETIRED')),private_content_ref TEXT NOT NULL,content_hash TEXT CHECK(content_hash IS NULL OR content_hash ~ '^[0-9a-f]{64}$'),published_by_principal_id UUID NOT NULL REFERENCES principals(id),published_at TIMESTAMPTZ NOT NULL DEFAULT now(),retired_by_principal_id UUID REFERENCES principals(id),retired_at TIMESTAMPTZ,UNIQUE(knowledge_scope,version));
CREATE TABLE methodology_version_knowledge(methodology_version_id UUID NOT NULL REFERENCES methodology_versions(id),authorized_knowledge_version_id UUID NOT NULL REFERENCES authorized_knowledge_versions(id),PRIMARY KEY(methodology_version_id,authorized_knowledge_version_id));
